1	import * as backend from "../backend";
2	import * as identityPlatform from "../../../gcp/identityPlatform";
3	import * as events from "../../../functions/events";
4	import { FirebaseError } from "../../../error";
5	import { cloneDeep } from "../../../utils";
6	import { Name, noop, Service } from "./index";
7	
8	export class AuthBlockingService implements Service {
9	  name: Name;
10	  api: string;
11	  triggerQueue: Promise<void>;
12	
13	  constructor() {
14	    this.name = "authblocking";
15	    this.api = "identitytoolkit.googleapis.com";
16	    this.triggerQueue = Promise.resolve();
17	    this.ensureTriggerRegion = noop;
18	  }
19	
20	  ensureTriggerRegion: (ep: backend.Endpoint & backend.EventTriggered) => Promise<void>;
21	
22	  /**
23	   * Ensure that at most one blocking function of that type exists and merges identity platform options on our backend to deploy.
24	   * @param endpoint the Auth Blocking endpoint
25	   * @param wantBackend the backend we are deploying
26	   */
27	  validateTrigger(endpoint: backend.Endpoint, wantBackend: backend.Backend): void {
28	    if (!backend.isBlockingTriggered(endpoint)) {
29	      return; // this should never happen
30	    }
31	    const blockingEndpoints = backend
32	      .allEndpoints(wantBackend)
33	      .filter((ep) => backend.isBlockingTriggered(ep)) as (backend.Endpoint &
34	      backend.BlockingTriggered)[];
35	    if (
36	      blockingEndpoints.find(
37	        (ep) =>
38	          ep.blockingTrigger.eventType === endpoint.blockingTrigger.eventType &&
39	          ep.id !== endpoint.id,
40	      )
41	    ) {
42	      throw new FirebaseError(
43	        `Can only create at most one Auth Blocking Trigger for ${endpoint.blockingTrigger.eventType} events`,
44	      );
45	    }
46	  }
47	
48	  private configChanged(
49	    newConfig: identityPlatform.BlockingFunctionsConfig,
50	    config: identityPlatform.BlockingFunctionsConfig,
51	  ) {
52	    if (
53	      newConfig.triggers?.beforeCreate?.functionUri !==
54	        config.triggers?.beforeCreate?.functionUri ||
55	      newConfig.triggers?.beforeSignIn?.functionUri !==
56	        config.triggers?.beforeSignIn?.functionUri ||
57	      newConfig.triggers?.beforeSendEmail?.functionUri !==
58	        config.triggers?.beforeSendEmail?.functionUri ||
59	      newConfig.triggers?.beforeSendSms?.functionUri !== config.triggers?.beforeSendSms?.functionUri
60	    ) {
61	      return true;
62	    }
63	    if (
64	      !!newConfig.forwardInboundCredentials?.accessToken !==
65	        !!config.forwardInboundCredentials?.accessToken ||
66	      !!newConfig.forwardInboundCredentials?.idToken !==
67	        !!config.forwardInboundCredentials?.idToken ||
68	      !!newConfig.forwardInboundCredentials?.refreshToken !==
69	        !!config.forwardInboundCredentials?.refreshToken
70	    ) {
71	      return true;
72	    }
73	    return false;
74	  }
75	
76	  private async registerTriggerLocked(
77	    endpoint: backend.Endpoint & backend.BlockingTriggered,
78	  ): Promise<void> {
79	    const newBlockingConfig = await identityPlatform.getBlockingFunctionsConfig(endpoint.project);
80	    const oldBlockingConfig = cloneDeep(newBlockingConfig);
81	
82	    if (endpoint.blockingTrigger.eventType === events.v1.BEFORE_CREATE_EVENT) {
83	      newBlockingConfig.triggers = {
84	        ...newBlockingConfig.triggers,
85	        beforeCreate: {
86	          functionUri: endpoint.uri!,
87	        },
88	      };
89	    } else if (endpoint.blockingTrigger.eventType === events.v1.BEFORE_SIGN_IN_EVENT) {
90	      newBlockingConfig.triggers = {
91	        ...newBlockingConfig.triggers,
92	        beforeSignIn: {
93	          functionUri: endpoint.uri!,
94	        },
95	      };
96	    } else if (endpoint.blockingTrigger.eventType === events.v1.BEFORE_SEND_EMAIL_EVENT) {
97	      newBlockingConfig.triggers = {
98	        ...newBlockingConfig.triggers,
99	        beforeSendEmail: {
100	          functionUri: endpoint.uri!,
101	        },
102	      };
103	    } else if (endpoint.blockingTrigger.eventType === events.v1.BEFORE_SEND_SMS_EVENT) {
104	      newBlockingConfig.triggers = {
105	        ...newBlockingConfig.triggers,
106	        beforeSendSms: {
107	          functionUri: endpoint.uri!,
108	        },
109	      };
110	    } else {
111	      throw new FirebaseError(
112	        `Received invalid blocking trigger event type ${endpoint.blockingTrigger.eventType}`,
113	      );
114	    }
115	
116	    newBlockingConfig.forwardInboundCredentials = {
117	      ...oldBlockingConfig.forwardInboundCredentials,
118	      ...endpoint.blockingTrigger.options,
119	    };
120	
121	    if (!this.configChanged(newBlockingConfig, oldBlockingConfig)) {
122	      return;
123	    }
124	
125	    await identityPlatform.setBlockingFunctionsConfig(endpoint.project, newBlockingConfig);
126	  }
127	
128	  /**
129	   * Registers the auth blocking trigger to identity platform.
130	   * @param ep the blocking endpoint
131	   */
132	  registerTrigger(ep: backend.Endpoint): Promise<void> {
133	    if (!backend.isBlockingTriggered(ep)) {
134	      return Promise.resolve(); // this should never happen
135	    }
136	    this.triggerQueue = this.triggerQueue.then(() => this.registerTriggerLocked(ep));
137	    return this.triggerQueue;
138	  }
139	
140	  private async unregisterTriggerLocked(
141	    endpoint: backend.Endpoint & backend.BlockingTriggered,
142	  ): Promise<void> {
143	    const blockingConfig = await identityPlatform.getBlockingFunctionsConfig(endpoint.project);
144	    if (
145	      endpoint.uri !== blockingConfig.triggers?.beforeCreate?.functionUri &&
146	      endpoint.uri !== blockingConfig.triggers?.beforeSignIn?.functionUri &&
147	      endpoint.uri !== blockingConfig.triggers?.beforeSendEmail?.functionUri &&
148	      endpoint.uri !== blockingConfig.triggers?.beforeSendSms?.functionUri
149	    ) {
150	      return;
151	    }
152	
153	    // There is a possibility that the user changed the registration on identity platform,
154	    // to prevent 400 errors on every create and/or sign in on the app, we will treat
155	    // the blockingConfig as the source of truth and only delete matching uri's.
156	    if (endpoint.uri === blockingConfig.triggers?.beforeCreate?.functionUri) {
157	      delete blockingConfig.triggers?.beforeCreate;
158	    }
159	    if (endpoint.uri === blockingConfig.triggers?.beforeSignIn?.functionUri) {
160	      delete blockingConfig.triggers?.beforeSignIn;
161	    }
162	    if (endpoint.uri === blockingConfig.triggers?.beforeSendEmail?.functionUri) {
163	      delete blockingConfig.triggers?.beforeSendEmail;
164	    }
165	    if (endpoint.uri === blockingConfig.triggers?.beforeSendSms?.functionUri) {
166	      delete blockingConfig.triggers?.beforeSendSms;
167	    }
168	
169	    await identityPlatform.setBlockingFunctionsConfig(endpoint.project, blockingConfig);
170	  }
171	
172	  /**
173	   * Un-registers the auth blocking trigger from identity platform. If the endpoint uri is not on the resource, we do nothing.
174	   * @param ep the blocking endpoint
175	   */
176	  unregisterTrigger(ep: backend.Endpoint): Promise<void> {
177	    if (!backend.isBlockingTriggered(ep)) {
178	      return Promise.resolve(); // this should never happen
179	    }
180	    this.triggerQueue = this.triggerQueue.then(() => this.unregisterTriggerLocked(ep));
181	    return this.triggerQueue;
182	  }
183	}
