68	  const pathParts = channel.name.split("/");
69	
70	  const res = await client.post<Channel, Operation>(pathParts.slice(0, -1).join("/"), channel, {
71	    queryParams: { channelId: last(pathParts)! },
72	  });
73	  return res.body;
74	}
