78	 * Only set fields are updated.
79	 */
80	export async function updateChannel(channel: Channel): Promise<Channel> {
81	  const res = await client.put<Channel, Channel>(channel.name, channel, {
82	    queryParams: {
83	      updateMask: fieldMasks(channel).join(","),
84	    },
85	  });
86	  return res.body;
87	}
