[metadata] {"type": "create", "filePath": "/workspace/repo/src/gcp/ailogic.ts", "content": "import { Client } from "../apiv2";
import { aiLogicOrigin } from "../api";
import { FirebaseError, getErrStatus } from "../error";
import * as events from "../functions/events";

export const API_VERSION = "v1beta";

/** An exported HTTP API client instance used to communicate with the AI Logic API. */
export const client = new Client({
  urlPrefix: aiLogicOrigin(),
  auth: true,
  apiVersion: API_VERSION,
});

/** The subset of an endpoint required to manage an AI Logic blocking trigger. */
export interface Endpoint {
  id: string;
  project: string;
  region: string;
  blockingTrigger: {
    eventType: string;
    options?: Record<string, unknown>;
  };
}

interface Trigger {
  cloudFunction: {
    id: string;
    locationId: string;
  };
}

/**
 * Maps an AI Logic event type to the API trigger ID.
 */
function triggerId(eventType: string): string {
  switch (eventType) {
    case events.v2.AI_LOGIC_BEFORE_GENERATE_CONTENT:
      return "before-generate-content";
    case events.v2.AI_LOGIC_AFTER_GENERATE_CONTENT:
      return "after-generate-content";
    default:
      throw new FirebaseError(`Received invalid AI Logic blocking trigger event type ${eventType}`);
  }
}

/**
 * Determines the location segment for a trigger. Global triggers (no
 * regionalWebhook option) use "global"; regional triggers use the endpoint region.
 */
function locationId(endpoint: Endpoint): string {
  return endpoint.blockingTrigger.options?.regionalWebhook ? endpoint.region : "global";
}

function triggerBody(endpoint: Endpoint): Trigger {
  return {
    cloudFunction: {
      id: endpoint.id,
      locationId: endpoint.region,
    },
  };
}

/**
 * Creates a new AI Logic blocking trigger via POST. If the POST fails with an
 * HTTP 409 (conflict), falls back to a PATCH to update the existing trigger. For
 * any other POST failure, the error is rethrown without calling PATCH.
 * @param endpoint the AI Logic blocking endpoint
 */
export async function upsertBlockingFunction(endpoint: Endpoint): Promise<void> {
  const location = locationId(endpoint);
  const id = triggerId(endpoint.blockingTrigger.eventType);
  const body = triggerBody(endpoint);
  try {
    await client.post<Trigger, unknown>(
      `projects/${endpoint.project}/locations/${location}/triggers`,
      body,
      { queryParams: { triggerId: id, validateOnly: "false" } },
    );
  } catch (err: unknown) {
    if (getErrStatus(err) !== 409) {
      throw err;
    }
    await client.patch<Trigger, unknown>(
      `projects/${endpoint.project}/locations/${location}/triggers/${id}`,
      body,
      { queryParams: { allowMissing: "false", validateOnly: "false" } },
    );
  }
}

/**
 * Deletes an AI Logic blocking trigger. Uses allowMissing: "true" so deletion is
 * idempotent.
 * @param endpoint the AI Logic blocking endpoint
 */
export async function deleteBlockingFunction(endpoint: Endpoint): Promise<void> {
  const location = locationId(endpoint);
  const id = triggerId(endpoint.blockingTrigger.eventType);
  await client.delete(`projects/${endpoint.project}/locations/${location}/triggers/${id}`, {
    queryParams: { allowMissing: "true", validateOnly: "false" },
  });
}
