  api: string;
  triggerQueue: Promise<void>;

  constructor() {
    this.name = "ailogic";
    this.api = "firebasevertexai.googleapis.com";
    this.triggerQueue = Promise.resolve();
    this.ensureTriggerRegion = noop;
  }

